function extractList(response, keys) {
  let value = response?.data ?? response?.body ?? response;

  if (Array.isArray(value)) return value;
  if (!value || typeof value !== 'object') return [];

  for (const key of keys) {
    if (Array.isArray(value[key])) return value[key];
  }

  if (value.data && typeof value.data === 'object') {
    if (Array.isArray(value.data)) return value.data;

    for (const key of keys) {
      if (Array.isArray(value.data[key])) return value.data[key];
    }
  }

  return [];
}

const strategies = extractList(
  $('03 - Get Strategies').first().json,
  ['strategies', 'items', 'results']
);

const opportunities = extractList(
  $('04 - Get Opportunities').first().json,
  ['opportunities', 'items', 'results']
);

const risks = extractList(
  $('05 - Get Risks').first().json,
  ['risks', 'items', 'results']
);

// Chuẩn hóa chiến lược
const latestStrategies = strategies.slice(-15).map(s => ({
  title: String(s.strategy_title ?? s.title ?? '').trim(),
  objective: String(s.objective ?? '').trim(),
  action_steps: Array.isArray(s.action_steps)
    ? s.action_steps.slice(0, 5)
    : [],
  expected_outcome: String(s.expected_outcome ?? '')
    .trim()
    .slice(0, 200)
}));

// Chuẩn hóa cơ hội
const selectedOpportunities = opportunities.slice(0, 20).map(o => ({
  title: String(o.title ?? '').trim(),
  score: o.score ?? o.potential_score ?? 0,
  priority: String(o.priority ?? '').trim(),
  reason: String(o.reason ?? o.description ?? '')
    .trim()
    .slice(0, 200),
  evidence: o.evidence ?? null
}));

// Chuẩn hóa rủi ro theo schema backend
const selectedRisks = risks.slice(0, 20).map(r => ({
  title: String(r.title ?? r.risk_title ?? '').trim(),
  score: r.score ?? null,
  severity: String(r.severity ?? '').trim(),
  reason: String(r.reason ?? r.impact_analysis ?? '')
    .trim()
    .slice(0, 200),
  evidence: r.evidence ?? null
}));

const analyzedAt = new Date().toISOString();

const sourceCounts = {
  strategies: latestStrategies.length,
  opportunities: selectedOpportunities.length,
  risks: selectedRisks.length
};

const hasInputData =
  sourceCounts.strategies > 0 ||
  sourceCounts.opportunities > 0 ||
  sourceCounts.risks > 0;

// Yêu cầu AI trả về JSON thuần, không tạo dữ liệu giả
const prompt = `Bạn là hệ thống tổng hợp báo cáo chiến lược cạnh tranh dựa trên dữ liệu.

NHIỆM VỤ:
Tạo báo cáo bằng tiếng Việt từ dữ liệu JSON đầu vào.

QUY TẮC BẮT BUỘC:
1. Chỉ sử dụng thông tin có trong INPUT.
2. Không bịa tên công ty, số liệu, sự kiện hoặc xu hướng.
3. Không tự suy đoán ngành kinh doanh khi dữ liệu chưa xác định.
4. Phân biệt dữ kiện và nhận định.
5. Nếu thiếu dữ liệu, ghi rõ trong limitations.
6. Không trả về Markdown, dấu sao hoặc code fence.
7. Chỉ trả về một JSON object hợp lệ.
8. Các trường phải đúng tên và kiểu dữ liệu trong schema.
9. Không khẳng định kết quả tương lai chắc chắn xảy ra.
10. Không tạo khuyến nghị chung chung không liên quan đến dữ liệu.

SCHEMA JSON BẮT BUỘC:
{
  "report_title": "string",
  "executive_summary": "string",
  "key_findings": ["string"],
  "opportunities": ["string"],
  "risks": ["string"],
  "strategic_recommendations": ["string"],
  "limitations": ["string"]
}

YÊU CẦU:
- key_findings: phát hiện có bằng chứng từ dữ liệu.
- opportunities: cơ hội dựa trên dữ liệu WF07.
- risks: rủi ro dựa trên dữ liệu WF08.
- strategic_recommendations: hành động cụ thể dựa trên các phát hiện, cơ hội và rủi ro.
- limitations: nêu rõ dữ liệu thiếu hoặc chưa đủ để kết luận.
- Nếu không có dữ liệu cho một mục, trả về mảng rỗng hoặc nêu hạn chế phù hợp.
- Không dùng dữ liệu của chiến lược để khẳng định rằng một hành động đã thành công nếu không có bằng chứng.

INPUT:
${JSON.stringify({
  strategies: latestStrategies,
  opportunities: selectedOpportunities,
  risks: selectedRisks,
  source_counts: sourceCounts
})}

Chỉ trả về JSON hợp lệ. Không giải thích ngoài JSON.`;

return [{
  json: {
    analyzed_at: analyzedAt,
    strategies: latestStrategies,
    opportunities: selectedOpportunities,
    risks: selectedRisks,
    source_counts: sourceCounts,
    has_input_data: hasInputData,
    prompt
  }
}];

const result = $input.first().json;

const raw =
  result.content ??
  result.text ??
  result.response ??
  result.output ??
  result.message?.content ??
  result.choices?.[0]?.message?.content;

if (typeof raw !== 'string' || !raw.trim()) {
  return [{
    json: {
      parse_ok: false,
      parse_error: 'AI không trả về nội dung văn bản hợp lệ.'
    }
  }];
}

try {
  const clean = raw
    .trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/, '')
    .trim();

  const parsed = JSON.parse(clean);

  const requiredStrings = [
    'report_title',
    'executive_summary'
  ];

  const requiredArrays = [
    'key_findings',
    'opportunities',
    'risks',
    'strategic_recommendations',
    'limitations'
  ];

  for (const field of requiredStrings) {
    if (
      typeof parsed[field] !== 'string' ||
      !parsed[field].trim()
    ) {
      throw new Error(`Trường ${field} không hợp lệ.`);
    }
  }

  for (const field of requiredArrays) {
    if (
      !Array.isArray(parsed[field]) ||
      !parsed[field].every(v => typeof v === 'string')
    ) {
      throw new Error(`Trường ${field} phải là mảng chuỗi.`);
    }
  }

  return [{
    json: {
      ...parsed,
      parse_ok: true
    }
  }];
} catch (error) {
  return [{
    json: {
      parse_ok: false,
      parse_error:
        'AI trả về Markdown hoặc JSON không đúng schema: ' +
        error.message,
      raw_response: raw
    }
  }];
}

return $input.all().map(item => {
  const d = item.json;
  const errors = [];
  if (d.parse_ok !== true) errors.push(d.parse_error || 'Không phân tích được JSON AI.');
  for (const field of ['report_title', 'executive_summary']) {
    if (typeof d[field] !== 'string' || !d[field].trim()) errors.push(`Thiếu hoặc sai kiểu dữ liệu: ${field}.`);
  }
  for (const field of ['key_findings', 'opportunities', 'risks', 'strategic_recommendations', 'limitations']) {
    if (!Array.isArray(d[field]) || !d[field].every(value => typeof value === 'string')) errors.push(`${field} phải là mảng chuỗi.`);
  }
  if (Array.isArray(d.strategic_recommendations) && d.strategic_recommendations.length < 2) errors.push('Cần ít nhất 2 khuyến nghị chiến lược.');
  return { json: { ...d, is_valid: errors.length === 0, validation_errors: errors } };
});

